// Cloudflare Email Service adapter over the Workers `send_email` binding.
// All Cloudflare-specific shapes and error codes stay here; only the
// internal `EmailProvider` contract is exposed.
// Docs: https://developers.cloudflare.com/email-service/api/send-emails/workers-api/

import type { EmailProvider, EmailResult, SendEmailRequest } from "@surescore/shared";

export interface CloudflareEmailProviderConfig {
	/** The Workers `send_email` binding (`SendEmail`, generated by `wrangler types`). */
	binding: SendEmail | undefined;
	/** Address on a domain onboarded to Email Service, e.g. "no-reply@example.com". */
	fromAddress: string;
	fromName?: string;
}

export class CloudflareEmailProvider implements EmailProvider {
	readonly id = "cloudflare-email";

	constructor(private readonly config: CloudflareEmailProviderConfig) {}

	async send({ to, subject, text, html }: SendEmailRequest): Promise<EmailResult> {
		const { binding, fromAddress, fromName } = this.config;
		if (!binding) throw new Error("The EMAIL (send_email) binding is not configured.");
		if (!fromAddress) throw new Error("EMAIL_FROM_ADDRESS is not configured.");
		try {
			const { messageId } = await binding.send({
				to,
				from: fromName ? { email: fromAddress, name: fromName } : fromAddress,
				subject,
				text,
				...(html && { html }),
			});
			return { provider: this.id, messageId: messageId ?? null };
		} catch (error) {
			// Failures carry a `code`, e.g. E_SENDER_NOT_VERIFIED, E_RECIPIENT_SUPPRESSED, E_RATE_LIMIT_EXCEEDED.
			const code = (error as { code?: string }).code ?? "UNKNOWN";
			throw new Error(`Cloudflare Email Service send failed (${code}): ${(error as Error).message}`, { cause: error });
		}
	}
}
